const {fitDataAsync, OPTIMIZERS} = DataScience;
const {vec} = NMath;
const {vertices} = await IO.loadMesh("/assets/bunny.obj");
if (vertices.length === 0) throw new Error("The bunny mesh contains no vertices");

// Center and scale the vertices; rotate them so the bunny is upright in the 3D plot.
const points = vertices.map(vertex => vec(...vertex));
const mean = points.reduce((sum, point) => sum.add(point), vec.zero(3)).scale(1 / points.length);
const centered = points.map(point => point.sub(mean));
const scale = Math.max(...centered.flatMap(point => point.components.map(Math.abs)));
if (!Number.isFinite(scale) || scale === 0) throw new Error("The bunny mesh has invalid coordinates");
const targets = centered.map(point => {
    const [x, y, z] = point.scale(1 / scale).components;
    return vec(z, x, y);
});
const bounds = [0, 1, 2].map(axis => [
    Math.min(...targets.map(point => point.components[axis])),
    Math.max(...targets.map(point => point.components[axis])),
]);
const randomPoint = () => vec(...bounds.map(([min, max]) => min + Math.random() * (max - min)));

// Match the velocity of straight paths from random bounding-box points to bunny vertices.
const samples = Array.from({length: 12000}, () => {
    const x0 = randomPoint();
    const x1 = targets[Math.floor(Math.random() * targets.length)];
    const t = Math.random();
    return {
        input: vec(...x0.scale(1 - t).add(x1.scale(t)).components, t),
        velocity: x1.sub(x0),
    };
});

// A single symbolic network predicts all three velocity components.
const field = NeuralNet.builder()
    .input(4)
    .layer(24)
    .layer(24)
    .layer(3, NeuralNet.ACTIVATIONS.linear)
    .build();

const initial = Array.from({length: 800}, randomPoint);
const plot = IO.plotPointCloud(targets, {aspect: "equal", radius: 0.008, color: [0.4, 0.4, 0.4]});
const moving = plot.add(initial, {radius: 0.012, color: [1, 0, 0]});
const arrows = plot.addLines([], {color: [0.35, 0.65, 1], radius: 0.003});
// Invisible points keep a stable view while the samples and arrows move.
plot.add([[-1.3, -1.3, -1.3], [1.3, 1.3, 1.3]], {color: [0, 0, 0]});
const steps = 100;
let trajectory;

// Show a sparse 3D grid of capped velocity arrows.
const fieldLines = t => {
    const lines = [];
    for (let x = -1; x <= 1; x += 0.5) {
        for (let y = -1; y <= 1; y += 0.5) {
            for (let z = -1; z <= 1; z += 0.5) {
                const start = vec(x, y, z);
                const velocity = vec(...field.eval(vec(x, y, z, t)));
                const length = velocity.length();
                if (length < 1e-8) continue;
                const delta = velocity.scale(Math.min(0.1, 0.2 / length));
                const end = start.add(delta);
                const [dx, dy, dz] = delta.components;
                const perpendicular = Math.abs(dx) + Math.abs(dy) > 1e-8
                    ? vec(-dy, dx, 0) : vec(0, -dz, dy);
                const side = perpendicular.scale(0.15 * delta.length() / perpendicular.length());
                const head = delta.scale(0.3);
                lines.push([start, end], [end, end.sub(head).add(side)], [end, end.sub(head).sub(side)]);
            }
        }
    }
    return lines;
};

const showTime = t => {
    if (!trajectory) return;
    moving.update(trajectory[Math.round(t * steps)], {color: [1 - t, t, 0]});
    arrows.update(fieldLines(t));
    plot.render();
};

const ui = IO.UI(
    {type: "canvas", value: () => plot},
    {type: "slider", value: () => ({
        title: "t:", min: 0, max: 1, step: 1 / steps, value: 0,
        onChange: showTime,
    })},
);

const {theta} = await fitDataAsync(
    samples.map(sample => sample.input),
    samples.map(sample => sample.velocity),
    field.model,
    {
        epochs: 5000,
        batch: 32,
        optimizer: OPTIMIZERS.ADAMW({learningRate: 0.005}),
        continuationEvery: 250,
        continuationFn: ({epoch, loss}) => console.log(`Epoch ${epoch + 1}, loss ${loss.toFixed(4)}`),
    },
);
field.setWeights(theta);

// Cache the Euler trajectories so the slider can move forwards and backwards.
trajectory = [initial];
for (let step = 0; step < steps; step++) {
    const t = step / steps;
    trajectory.push(trajectory[step].map(point => {
        const velocity = vec(...field.eval(vec(...point.components, t)));
        return point.add(velocity.scale(1 / steps));
    }));
}
showTime(0);
ui;
